from qiskit import QuantumCircuit
import numpy as np

# Create a new QuantumCircuit with 5 qubits
qc = QuantumCircuit(5)

# Apply Hadamard gates to all qubits
for qubit in range(5):
    qc.h(qubit)

# Apply controlled-phase gates
for qubit in range(5):
    for other_qubit in range(5):
        if qubit != other_qubit:
            qc.cp(np.pi / 2, qubit, other_qubit)

# Apply swap gates
for qubit in range(5):
    for other_qubit in range(qubit + 1, 5):
        qc.swap(qubit, other_qubit)

# Apply inverse QFT
for qubit in range(4, -1, -1):
    qc.h(qubit)
    for other_qubit in range(qubit + 1, 5):
        qc.cp(-np.pi / 2, qubit, other_qubit)

# Apply final Hadamard gates
for qubit in range(5):
    qc.h(qubit)

# Output the resulting QuantumCircuit
qc.draw()

