    for j in range(i + 1, 5):
        qc.cu3(2 * np.pi / 2**i, i, j, np.pi / 2)

# Apply Swap gates to all pairs of qubits
for i in range(5):
    for j in range(i + 1, 5):
        qc.swap(i, j)

# Apply Hadamard gates to all qubits again
for qubit in qreg:
    qc.h(qubit)

# Apply inverse QFT gates
for qubit in qreg:
    qc.h(qubit)
for i in range(5):
    for j in range(i + 1, 5):
        qc.cu3(-2 * np.pi / 2**i, i, j, np.pi / 2)
for i in range(5):
    for j in range(i + 1, 5):
        qc.swap(i, j)

# Measure all qubits
for qubit in qreg:
    qc.measure(qubit, creg[qubit])

